-- TravelXM Agent Portal · sample Costa Rica package catalogue.
-- Destinations and activities come from travelxm.com. Hotels are described, not named.
-- Prices, commission rates and schedules are SAMPLES until TravelXM loads its real packages.
-- Generated in one pass; edit by hand from here on.
-- Runs on `supabase db reset` (config.toml [db.seed]); safe to re-run by hand:
--   docker exec -i supabase_db_travelxm-learning psql -U postgres < supabase/seeds/portal.sql
-- Per-agent demo data (clients, bookings, …) is loaded by
-- public.portal_seed_demo(agent uuid), called from scripts/seed.mts.
-- schedule: days count from 1 and times are the trip's local time.

insert into public.packages (
  id, name, destination, description, trip_types, settings, price_per_person, duration_days,
  commission_rate, rating, review_count, image_url, gallery, highlights, inclusions,
  what_to_bring, kid_friendly, min_age, is_featured, featured_rank, schedule
) values
(
  1, 'Arenal & Manuel Antonio Classic', 'La Fortuna & Manuel Antonio',
