  true, 8, false, null,
  '[{"kind":"transport","title":"San José airport to San José hotel","imageUrl":"/imgs/packages/transfer-van.webp","description":"Private air-conditioned van with a bilingual driver. Stops along the way on request.","highlights":["Private transfer","Luggage help","Bottled water"],"startDay":1,"startTime":"14:00","endDay":1,"endTime":"15:00"},{"kind":"hotel","title":"Boutique hotel in the city","location":"San José","imageUrl":"/imgs/packages/san-jose.webp","description":"A comfortable hotel within walking distance of the historic centre. Breakfast included.","highlights":["Breakfast included","Walkable location"],"startDay":1,"startTime":"15:00","endDay":5,"endTime":"09:00"},{"kind":"tour","title":"San José city walk","location":"San José","imageUrl":"/imgs/packages/san-jose.webp","description":"Walk the historic centre, the National Theatre and the Central Market with a local guide.","highlights":["Local guide","Central Market tasting"],"startDay":2,"startTime":"09:00","endDay":2,"endTime":"12:00"},{"kind":"tour","title":"Home-style Costa Rican lunch","location":"Central Valley","imageUrl":"/imgs/packages/typical-lunch.webp","description":"A casado made the traditional way, with rice, beans, plantain and fresh salad.","highlights":["Vegetarian option available"],"startDay":2,"startTime":"12:30","endDay":2,"endTime":"14:00"},{"kind":"tour","title":"Poás Volcano crater lookout","location":"Poás","imageUrl":"/imgs/packages/poas-lookout.webp","description":"Stand at the rim of one of the world''s largest active craters. Go early, before the clouds settle.","highlights":["Timed park entrance included","Short, paved walk","Subject to volcanic activity"],"startDay":3,"startTime":"07:30","endDay":3,"endTime":"11:00"},{"kind":"tour","title":"Coffee and cacao farm visit","location":"Central Valley","imageUrl":"/imgs/packages/countryside.webp","description":"Follow the bean from plant to cup on a family farm, then taste the coffee and make your own chocolate.","highlights":["