  '[{"kind":"transport","title":"San José airport to Uvita","imageUrl":"/imgs/packages/transfer-van.webp","description":"Private air-conditioned van with a bilingual driver. Stops along the way on request.","highlights":["Private transfer","Luggage help","Bottled water"],"startDay":1,"startTime":"09:00","endDay":1,"endTime":"13:30"},{"kind":"hotel","title":"Jungle eco-lodge","location":"Uvita","imageUrl":"/imgs/packages/river-lodge.webp","description":"Cabins in the hills above Marino Ballena, with sea views. Breakfast included.","highlights":["Breakfast included","Sea views"],"startDay":1,"startTime":"14:00","endDay":4,"endTime":"09:00"},{"kind":"tour","title":"Marino Ballena whale''s tail walk","location":"Uvita","imageUrl":"/imgs/packages/whale-tail.webp","description":"Walk out on the sandbar shaped like a whale''s tail at low tide. Timing follows the tide.","highlights":["Park entrance included","Timing follows the tide"],"startDay":2,"startTime":"07:30","endDay":2,"endTime":"10:00"},{"kind":"tour","title":"Whale-watching boat","location":"Uvita","imageUrl":"/imgs/packages/humpback.webp","description":"Head out with a marine guide to look for humpbacks and dolphins. Whales are seasonal, from December to April and July to November.","highlights":["Marine guide","Seasonal: Dec to Apr, Jul to Nov"],"startDay":2,"startTime":"13:00","endDay":2,"endTime":"16:30"},{"kind":"tour","title":"Hidden waterfall hike","location":"Uvita","imageUrl":"/imgs/packages/waterfall-couple.webp","description":"A rainforest hike to a waterfall and swimming hole with few other visitors.","highlights":["Local guide","Bring water shoes"],"startDay":3,"startTime":"08:00","endDay":3,"endTime":"11:00"},{"kind":"transport","title":"Uvita to Drake Bay","imageUrl":"/imgs/packages/transfer-van.webp","description":"Private van to Sierpe, then a boat through the mangroves to the lodge.","highlights":["Private transfer","Luggage help","Bottled water"],"startDay":4,"startTime":"09:00","endDay":4,"end