  '[{"kind":"transport","title":"San José airport to Tortuguero","imageUrl":"/imgs/packages/transfer-van.webp","description":"Private van to the dock, then a boat along the canals to the lodge.","highlights":["Private transfer","Luggage help","Bottled water"],"startDay":1,"startTime":"07:00","endDay":1,"endTime":"12:30"},{"kind":"hotel","title":"Canal-side jungle lodge","location":"Tortuguero","imageUrl":"/imgs/packages/tortuguero-kayak.webp","description":"Reached only by boat, with gardens on the canal. All meals included.","highlights":["All meals included","Boat access only"],"startDay":1,"startTime":"12:30","endDay":3,"endTime":"09:00"},{"kind":"tour","title":"Sea turtle conservation visit","location":"Tortuguero","imageUrl":"/imgs/packages/baby-turtles.webp","description":"Learn how the village went from hunting turtles to protecting them.","highlights":["Supports local conservation"],"startDay":1,"startTime":"14:30","endDay":1,"endTime":"16:00"},{"kind":"tour","title":"Night turtle watching","location":"Tortuguero","imageUrl":"/imgs/sea-turtles.webp","description":"With a certified guide, watch green turtles come ashore to nest. Seasonal, from July to October.","highlights":["Certified local guide","No flash or phones on the beach","Seasonal: July to October"],"startDay":1,"startTime":"20:00","endDay":1,"endTime":"22:30"},{"kind":"tour","title":"Tortuguero canal boat safari","location":"Tortuguero","imageUrl":"/imgs/capuchin-tortuguero.webp","description":"Glide along the canals at dawn looking for monkeys, caimans, herons and toucans.","highlights":["Naturalist boat captain","Park entrance included"],"startDay":2,"startTime":"06:30","endDay":2,"endTime":"09:30"},{"kind":"tour","title":"Canal kayak","location":"Tortuguero","imageUrl":"/imgs/packages/tortuguero-kayak.webp","description":"Paddle the quieter side channels where motorboats do not go.","highlights":["Kayak and guide included","Calm water"],"startDay":2,"startTime":"14:00","endDay":2,"endTime":"16: