  '[{"kind":"transport","title":"San José airport to La Fortuna","imageUrl":"/imgs/packages/transfer-van.webp","description":"Private air-conditioned van with a bilingual driver. Stops along the way on request.","highlights":["Private transfer","Luggage help","Bottled water"],"startDay":1,"startTime":"10:00","endDay":1,"endTime":"13:30"},{"kind":"hotel","title":"Volcano-view lodge","location":"La Fortuna","imageUrl":"/imgs/packages/pool-suite.webp","description":"A rainforest lodge with views of Arenal, thermal pools and breakfast included.","highlights":["Breakfast included","Volcano views","Thermal pools"],"startDay":1,"startTime":"15:00","endDay":4,"endTime":"11:00"},{"kind":"tour","title":"Volcanic hot springs evening","location":"La Fortuna","imageUrl":"/imgs/rainforest-valley-la-fortuna.webp","description":"Unwind in thermal pools warmed by the volcano, with dinner at the springs.","highlights":["Thermal pools at several temperatures","Dinner included","Towels provided"],"startDay":1,"startTime":"17:00","endDay":1,"endTime":"20:00"},{"kind":"tour","title":"Safari float on the river","location":"La Fortuna","imageUrl":"/imgs/packages/river-kayak.webp","description":"A gentle float downstream looking for sloths, iguanas and river birds. No paddling experience needed.","highlights":["Good for all ages","Fresh fruit snack"],"startDay":2,"startTime":"08:30","endDay":2,"endTime":"11:30"},{"kind":"tour","title":"Hanging bridges walk","location":"Arenal","imageUrl":"/imgs/packages/hanging-bridges.webp","description":"Cross suspension bridges through the rainforest canopy, looking for birds, monkeys and sloths from above.","highlights":["Canopy-level views","Easy, well-kept trail","Good for all ages"],"startDay":2,"startTime":"14:30","endDay":2,"endTime":"17:30"},{"kind":"tour","title":"Lake Arenal paddle and swim","location":"Lake Arenal","imageUrl":"/imgs/packages/arenal-lake.webp","description":"A calm morning on the lake with the volcano on the horizon, stopping to